#include <iostream>
#include <type_traits>

int main() {
    // Khai bao dung: moi con tro duoc dinh nghia ro rang
    int value = 42;
    int *valPtr = nullptr; // Khoi tao an toan bang nullptr

    // Kiem tra trang thai con tro rong
    if (valPtr == nullptr) {
        std::cout << "valPtr is currently null.\n";
    }

    // Gan dia chi hop le
    valPtr = &value;
    if (valPtr != nullptr) {
        std::cout << "valPtr now holds a valid address.\n";
    }

    // Minh hoa nullptr khong phai la so nguyen int
    static_assert(!std::is_integral_v<decltype(nullptr)>,
                  "nullptr is of type std::nullptr_t, not an integer!");

    return 0;
}

#include <iostream>

int main() {
    int a = 7;
    int *aPtr = &a; // aPtr nhan dia chi cua bien a

    // Doc gia tri truc tiep va gian tiep
    std::cout << "Value of a directly: " << a << '\n';
    std::cout << "Value of a via *aPtr: " << *aPtr << '\n';

    // Thay doi gia tri thong qua giai tham chieu (lvalue assignment)
    *aPtr = 99;
    std::cout << "Value of a after *aPtr = 99: " << a << '\n';

    // Kiem tra an toan truoc khi giai tham chieu
    int *nullPtr = nullptr;
    if (nullPtr != nullptr) {
        std::cout << *nullPtr << '\n'; // Khong bao gio chay vao day
    } else {
        std::cout << "nullPtr is safe: guarded against dereference.\n";
    }

    return 0;
}
